// Shapes the API sends, from its OpenAPI schema (src/api/schema.d.ts, generated by
// `make web-types`). The WebSocket events wrap them; they aren't in OpenAPI, so they're here.
import type { components } from './schema'

type Schemas = components['schemas']
export type TurnResponse = Schemas['TurnResponse']
export type BookResult = Schemas['BookResult']
export type Availability = Schemas['Availability']
export type Chip = Schemas['Chip']
export type Reply = Schemas['Reply']
export type ReplyItem = Schemas['ReplyItem']
export type Relaxation = Schemas['Relaxation']

/** Server -> client, per turn: "turn" (cards, chips, notes) as soon as retrieval is done,
 * then "reply" once the narration is written, then "done". */
export type ServerEvent =
  | ({ type: 'turn' } & TurnResponse)
  | { type: 'reply'; turn: number; reply: Reply }
  | { type: 'done'; turn: number }
  | { type: 'cancelled'; turn: number }
  | { type: 'error'; message: string }

export type ClientMessage =
  | { type: 'text'; text: string; limit?: number; narrate?: boolean }
  | { type: 'undo' }
  | { type: 'cancel' }
